//
// status_screen.v - SaveSiphon UI, 320x240, Pocket-style  (GENERATED by
// scripts/gen_screen.py - edit the generator, not this file)
//
// Black background, white text, grey secondary text, a white highlight bar
// for the selected menu row and a thin progress bar. 8x8 font, title at 2x.
// Inputs come from the clk_74a domain and change slowly; the clocks are
// declared asynchronous, so a torn frame is the worst case.
//

`default_nettype none

module status_screen (
    input  wire         clk,            // ~12.288 MHz pixel clock

    input  wire [2:0]   ui_mode,        // 0 busy, 1 menu, 2 result, 3 confirm
    input  wire [1:0]   menu_sel,
    input  wire [4:0]   status,
    input  wire [7:0]   progress,
    input  wire [2:0]   err_code,
    input  wire [2:0]   fault_code,
    input  wire [1:0]   cart_kind,
    input  wire [127:0] name_flat,
    input  wire [4:0]   name_len,
    input  wire [31:0]  code_flat,
    input  wire         code_len,
    input  wire [3:0]   save_label,
    input  wire [4:0]   rom_log2,
    input  wire [2:0]   mapper,
    input  wire [1:0]   done_what,
    input  wire [511:0] path_flat,

    output reg  [23:0]  rgb,
    output reg          de,
    output reg          hs,
    output reg          vs
);

localparam [9:0] H_BP = 10'd10, H_ACT = 10'd320, H_TOT = 10'd400;
localparam [9:0] V_BP = 10'd10, V_ACT = 10'd240, V_TOT = 10'd512;

localparam [23:0] C_BG    = 24'h000000;
localparam [23:0] C_FG    = 24'hF2F2F2;
localparam [23:0] C_DIM   = 24'h8C8C8C;
localparam [23:0] C_FAINT = 24'h3A3A3A;
localparam [23:0] C_BAR   = 24'hF2F2F2;     // highlight bar (text drawn black)
localparam [23:0] C_OK    = 24'h5BD27A;
localparam [23:0] C_BAD   = 24'hFF6159;

localparam [2:0] UI_BUSY = 3'd0, UI_MENU = 3'd1, UI_RESULT = 3'd2, UI_CONFIRM = 3'd3;

// text rows (top y of the 8 px glyph)
localparam [9:0] Y_TITLE = 10'd18;    // 2x, 16 px tall
localparam [9:0] Y_NAME  = 10'd50;
localparam [9:0] Y_SUB   = 10'd62;
localparam [9:0] Y_RULE  = 10'd78;
localparam [9:0] Y_R0    = 10'd92;
localparam [9:0] Y_R1    = 10'd112;
localparam [9:0] Y_R2    = 10'd132;
localparam [9:0] Y_R3    = 10'd152;
localparam [9:0] Y_I0    = 10'd176;
localparam [9:0] Y_I1    = 10'd188;
localparam [9:0] Y_HINT  = 10'd220;
localparam [9:0] Y_PBAR  = 10'd130;   // progress bar, 3 px tall

// ------------------------------------------------------------ font
reg [7:0] font [0:1023];
initial $readmemh("core/font.hex", font);

// ------------------------------------------------------------ timing
reg [9:0] x = 10'd0, y = 10'd0;
always @(posedge clk) begin
    if (x == H_TOT - 10'd1) begin
        x <= 10'd0;
        y <= (y == V_TOT - 10'd1) ? 10'd0 : y + 10'd1;
    end else begin
        x <= x + 10'd1;
    end
end
wire       active = (x >= H_BP) && (x < H_BP + H_ACT) && (y >= V_BP) && (y < V_BP + V_ACT);
wire [9:0] vx = x - H_BP;
wire [9:0] vy = y - V_BP;

// ------------------------------------------------------------ strings
reg [319:0] t_head, t_det1, t_det2, t_done, t_savev, t_romv, t_mapv, t_item;
reg [1:0]   item_idx;

always @(*) begin
    case (status)
    5'd0: t_head = {{9{8'h00}}, "Waiting for cartridge", {10{8'h00}}};
    5'd1: t_head = {{11{8'h00}}, "Reading cartridge", {12{8'h00}}};
    5'd2: t_head = {{11{8'h00}}, "No cartridge found", {11{8'h00}}};
    5'd3: t_head = {{11{8'h00}}, "Reading cartridge", {12{8'h00}}};
    5'd4: t_head = {{7{8'h00}}, "No save on this cartridge", {8{8'h00}}};
    5'd5: t_head = {{14{8'h00}}, "Reading save", {14{8'h00}}};
    5'd6: t_head = {{9{8'h00}}, "EEPROM did not answer", {10{8'h00}}};
    5'd7: t_head = {{11{8'h00}}, "Writing to SD card", {11{8'h00}}};
    5'd8: t_head = {{18{8'h00}}, "Done", {18{8'h00}}};
    5'd9: t_head = {{13{8'h00}}, "SD card error", {14{8'h00}}};
    5'd10: t_head = {{12{8'h00}}, "Too many backups", {12{8'h00}}};
    5'd11: t_head = {{9{8'h00}}, "SD card not responding", {9{8'h00}}};
    5'd12: t_head = {{14{8'h00}}, "Safety stop", {15{8'h00}}};
    5'd13: t_head = {{13{8'h00}}, "Ready to read", {14{8'h00}}};
    5'd14: t_head = {{13{8'h00}}, "Unstable read", {14{8'h00}}};
    5'd15: t_head = {{11{8'h00}}, "Cartridge changed", {12{8'h00}}};
    5'd16: t_head = {{15{8'h00}}, "Cancelled", {16{8'h00}}};
    5'd17: t_head = {{15{8'h00}}, "Verifying", {16{8'h00}}};
    5'd18: t_head = {{10{8'h00}}, "Cartridge power lost", {10{8'h00}}};
    5'd19: t_head = {{14{8'h00}}, "Reading ROM", {15{8'h00}}};
    5'd20: t_head = {{9{8'h00}}, "Unsupported cartridge", {10{8'h00}}};
    5'd21: t_head = {40{8'h00}};
    5'd22: t_head = {{11{8'h00}}, "Reading cartridge", {12{8'h00}}};
    default: t_head = {40{8'h00}};
    endcase
end

always @(*) begin
    case (status)
    5'd0: t_det1 = {40{8'h00}};
    5'd1: t_det1 = {40{8'h00}};
    5'd2: t_det1 = {{3{8'h00}}, "Insert a GB, GBC or GBA cartridge", {4{8'h00}}};
    5'd3: t_det1 = {40{8'h00}};
    5'd4: t_det1 = {40{8'h00}};
    5'd5: t_det1 = {40{8'h00}};
    5'd6: t_det1 = {{4{8'h00}}, "The save looks blank or the chip", {4{8'h00}}};
    5'd7: t_det1 = {40{8'h00}};
    5'd8: t_det1 = {40{8'h00}};
    5'd9: t_det1 = {{5{8'h00}}, "The file could not be written.", {5{8'h00}}};
    5'd10: t_det1 = {{7{8'h00}}, "Up to 99 backups per game.", {7{8'h00}}};
    5'd11: t_det1 = {40{8'h00}};
    5'd12: t_det1 = {{5{8'h00}}, "A cartridge write was blocked.", {5{8'h00}}};
    5'd13: t_det1 = {{3{8'h00}}, "This cartridge needs read commands", {3{8'h00}}};
    5'd14: t_det1 = {{8{8'h00}}, "Two reads did not match.", {8{8'h00}}};
    5'd15: t_det1 = {{6{8'h00}}, "The cartridge was removed or", {6{8'h00}}};
    5'd16: t_det1 = {40{8'h00}};
    5'd17: t_det1 = {40{8'h00}};
    5'd18: t_det1 = {{6{8'h00}}, "Power the Pocket off and on.", {6{8'h00}}};
    5'd19: t_det1 = {40{8'h00}};
    5'd20: t_det1 = {{3{8'h00}}, "This mapper is not supported yet.", {4{8'h00}}};
    5'd21: t_det1 = {40{8'h00}};
    5'd22: t_det1 = {40{8'h00}};
    default: t_det1 = {40{8'h00}};
    endcase
end

always @(*) begin
    case (status)
    5'd0: t_det2 = {40{8'h00}};
    5'd1: t_det2 = {40{8'h00}};
    5'd2: t_det2 = {{6{8'h00}}, "with the Pocket powered off.", {6{8'h00}}};
    5'd3: t_det2 = {40{8'h00}};
    5'd4: t_det2 = {40{8'h00}};
    5'd5: t_det2 = {40{8'h00}};
    5'd6: t_det2 = {{11{8'h00}}, "is not responding.", {11{8'h00}}};
    5'd7: t_det2 = {40{8'h00}};
    5'd8: t_det2 = {40{8'h00}};
    5'd9: t_det2 = {40{8'h00}};
    5'd10: t_det2 = {{7{8'h00}}, "Move some off the SD card.", {7{8'h00}}};
    5'd11: t_det2 = {40{8'h00}};
    5'd12: t_det2 = {{5{8'h00}}, "Nothing was written. Restart.", {6{8'h00}}};
    5'd13: t_det2 = {{2{8'h00}}, "on its bus. Its save is not changed.", {2{8'h00}}};
    5'd14: t_det2 = {{5{8'h00}}, "Clean the contacts and retry.", {6{8'h00}}};
    5'd15: t_det2 = {{9{8'h00}}, "swapped while reading.", {9{8'h00}}};
    5'd16: t_det2 = {40{8'h00}};
    5'd17: t_det2 = {40{8'h00}};
    5'd18: t_det2 = {40{8'h00}};
    5'd19: t_det2 = {40{8'h00}};
    5'd20: t_det2 = {40{8'h00}};
    5'd21: t_det2 = {40{8'h00}};
    5'd22: t_det2 = {40{8'h00}};
    default: t_det2 = {40{8'h00}};
    endcase
end

always @(*) begin
    case (done_what)
    2'd1: t_done = {{13{8'h00}}, "Save backed up", {13{8'h00}}};
    2'd2: t_done = {{13{8'h00}}, "ROM backed up", {14{8'h00}}};
    2'd3: t_done = {{9{8'h00}}, "Save and ROM backed up", {9{8'h00}}};
    default: t_done = {{18{8'h00}}, "Done", {18{8'h00}}};
    endcase
end

always @(*) begin
    case (save_label)
    4'd0: t_savev = {{30{8'h00}}, "None", {6{8'h00}}};
    4'd1: t_savev = {{24{8'h00}}, "SRAM 32 KB", {6{8'h00}}};
    4'd2: t_savev = {{23{8'h00}}, "Flash 64 KB", {6{8'h00}}};
    4'd3: t_savev = {{22{8'h00}}, "Flash 128 KB", {6{8'h00}}};
    4'd4: t_savev = {{22{8'h00}}, "EEPROM 512 B", {6{8'h00}}};
    4'd5: t_savev = {{23{8'h00}}, "EEPROM 8 KB", {6{8'h00}}};
    4'd6: t_savev = {{28{8'h00}}, "EEPROM", {6{8'h00}}};
    4'd7: t_savev = {{25{8'h00}}, "SRAM 2 KB", {6{8'h00}}};
    4'd8: t_savev = {{25{8'h00}}, "SRAM 8 KB", {6{8'h00}}};
    4'd9: t_savev = {{24{8'h00}}, "SRAM 32 KB", {6{8'h00}}};
    4'd10: t_savev = {{24{8'h00}}, "SRAM 64 KB", {6{8'h00}}};
    4'd11: t_savev = {{23{8'h00}}, "SRAM 128 KB", {6{8'h00}}};
    4'd12: t_savev = {{24{8'h00}}, "MBC2 512 B", {6{8'h00}}};
    default: t_savev = {40{8'h00}};
    endcase
end

always @(*) begin
    case (rom_log2)
    5'd15: t_romv = {{29{8'h00}}, "32 KB", {6{8'h00}}};
    5'd16: t_romv = {{29{8'h00}}, "64 KB", {6{8'h00}}};
    5'd17: t_romv = {{28{8'h00}}, "128 KB", {6{8'h00}}};
    5'd18: t_romv = {{28{8'h00}}, "256 KB", {6{8'h00}}};
    5'd19: t_romv = {{28{8'h00}}, "512 KB", {6{8'h00}}};
    5'd20: t_romv = {{30{8'h00}}, "1 MB", {6{8'h00}}};
    5'd21: t_romv = {{30{8'h00}}, "2 MB", {6{8'h00}}};
    5'd22: t_romv = {{30{8'h00}}, "4 MB", {6{8'h00}}};
    5'd23: t_romv = {{30{8'h00}}, "8 MB", {6{8'h00}}};
    5'd24: t_romv = {{29{8'h00}}, "16 MB", {6{8'h00}}};
    5'd25: t_romv = {{29{8'h00}}, "32 MB", {6{8'h00}}};
    default: t_romv = {40{8'h00}};
    endcase
end

always @(*) begin
    case (mapper)
    3'd0: t_mapv = {{26{8'h00}}, "ROM only", {6{8'h00}}};
    3'd1: t_mapv = {{30{8'h00}}, "MBC1", {6{8'h00}}};
    3'd2: t_mapv = {{30{8'h00}}, "MBC2", {6{8'h00}}};
    3'd3: t_mapv = {{30{8'h00}}, "MBC3", {6{8'h00}}};
    3'd5: t_mapv = {{30{8'h00}}, "MBC5", {6{8'h00}}};
    3'd7: t_mapv = {{27{8'h00}}, "Unknown", {6{8'h00}}};
    default: t_mapv = {40{8'h00}};
    endcase
end

always @(*) begin
    case (item_idx)
    2'd0: t_item = {{8{8'h00}}, "Back up save", {20{8'h00}}};
    2'd1: t_item = {{8{8'h00}}, "Back up ROM", {21{8'h00}}};
    2'd2: t_item = {{8{8'h00}}, "Back up save + ROM", {14{8'h00}}};
    2'd3: t_item = {{8{8'h00}}, "Rescan cartridge", {16{8'h00}}};
    default: t_item = {40{8'h00}};
    endcase
end

function [7:0] printable;
    input [7:0] c;
    printable = (c >= 8'h20 && c < 8'h7F) ? c : 8'h00;
endfunction

// cart name, centred; GBA adds " . CODE" to the subtitle
reg [319:0] t_name, t_sub, t_file, t_err;
reg [5:0]   nshift, flen;
integer i;
always @(*) begin
    t_name = {40{8'h00}};
    for (i = 0; i < 16; i = i + 1)
        if (i < name_len) t_name[319-8*i -: 8] = printable(name_flat[127-8*i -: 8]);
    nshift = (6'd40 - {1'b0, name_len}) >> 1;
    t_name = t_name >> {nshift, 3'b000};

    case (cart_kind)
    2'd1: t_sub = {{7{8'h00}}, {"Game Boy Advance  ", 8'h03, "  "}, code_flat[31:24], code_flat[23:16], code_flat[15:8], code_flat[7:0], {8{8'h00}}};
    2'd2: t_sub = {{16{8'h00}}, "Game Boy", {16{8'h00}}};
    2'd3: t_sub = {{13{8'h00}}, "Game Boy Color", {13{8'h00}}};
    default: t_sub = {40{8'h00}};
    endcase

    // file name after "/Assets/savesiphon/common/" (26 bytes), centred
    t_file = {40{8'h00}};
    flen   = 6'd0;
    for (i = 0; i < 36; i = i + 1) begin
        t_file[319-8*i -: 8] = printable(path_flat[511-8*(26+i) -: 8]);
        if (path_flat[511-8*(26+i) -: 8] != 8'h00) flen = i + 1;
    end
    t_file = t_file >> {((6'd40 - flen) >> 1), 3'b000};

    if (status == 5'd12) begin
        t_err = {{13{8'h00}}, "Guard code   ", {14{8'h00}}};
        t_err[319-8*25 -: 8] = "0" + {5'd0, fault_code};
    end else begin
        t_err = {{11{8'h00}}, "APF error code   ", {12{8'h00}}};
        t_err[319-8*27 -: 8] = "0" + {5'd0, err_code};
    end
end

wire st_bad  = (status == 5'd2) || (status == 5'd4) || (status == 5'd6) ||
               (status >= 5'd9 && status <= 5'd12) || (status == 5'd14) ||
               (status == 5'd15) || (status == 5'd18) || (status == 5'd20);
wire fatal   = (status == 5'd12) || (status == 5'd18);
wire is_gb   = cart_kind[1];
wire no_save = (save_label == 4'd0);

// ------------------------------------------------------------ stage A: where are we
reg [3:0]  slot_a;      // which text line, 0 = none
reg [5:0]  col_a;
reg [2:0]  fy_a, fx_a;
reg        act_a, title_a, bar_a, pbar_a, pfill_a, rule_a;
reg [1:0]  row_a;
wire       in_title = (vy >= Y_TITLE) && (vy < Y_TITLE + 10'd16) && (vx >= 10'd80) && (vx < 10'd240);
wire [9:0] tx = vx - 10'd80;
wire [9:0] ty = vy - Y_TITLE;

function in_row;
    input [9:0] yy, top;
    in_row = (yy >= top) && (yy < top + 10'd8);
endfunction

always @(posedge clk) begin
    act_a   <= active;
    title_a <= in_title;
    col_a   <= in_title ? {2'b00, tx[7:4]} : vx[8:3];
    fx_a    <= in_title ? tx[3:1] : vx[2:0];
    slot_a  <= 4'd0;
    fy_a    <= vy[2:0];
    row_a   <= 2'd0;
    if (in_title)              begin slot_a <= 4'd15; fy_a <= ty[3:1]; end
    else if (in_row(vy, Y_NAME)) begin slot_a <= 4'd1; fy_a <= vy - Y_NAME; end
    else if (in_row(vy, Y_SUB))  begin slot_a <= 4'd2; fy_a <= vy - Y_SUB;  end
    else if (in_row(vy, Y_R0))   begin slot_a <= 4'd3; fy_a <= vy - Y_R0; row_a <= 2'd0; end
    else if (in_row(vy, Y_R1))   begin slot_a <= 4'd4; fy_a <= vy - Y_R1; row_a <= 2'd1; end
    else if (in_row(vy, Y_R2))   begin slot_a <= 4'd5; fy_a <= vy - Y_R2; row_a <= 2'd2; end
    else if (in_row(vy, Y_R3))   begin slot_a <= 4'd6; fy_a <= vy - Y_R3; row_a <= 2'd3; end
    else if (in_row(vy, Y_I0))   begin slot_a <= 4'd7; fy_a <= vy - Y_I0; end
    else if (in_row(vy, Y_I1))   begin slot_a <= 4'd8; fy_a <= vy - Y_I1; end
    else if (in_row(vy, Y_HINT)) begin slot_a <= 4'd9; fy_a <= vy - Y_HINT; end

    // menu highlight bar: 16 px tall around the selected row, x 40..279
    bar_a <= (ui_mode == UI_MENU) && (vx >= 10'd40) && (vx < 10'd280) &&
             (vy >= Y_R0 - 10'd4 + {menu_sel, 4'b0} + {menu_sel, 2'b0}) &&
             (vy <  Y_R0 + 10'd12 + {menu_sel, 4'b0} + {menu_sel, 2'b0});
    // progress bar while busy: x 64..255, 3 px
    pbar_a  <= (ui_mode == UI_BUSY) && (status != 5'd0) && (vx >= 10'd64) && (vx < 10'd256) &&
               (vy >= Y_PBAR) && (vy < Y_PBAR + 10'd3);
    pfill_a <= ({2'b00, vx - 10'd64} < ({2'b00, progress} * 10'd3 >> 2));
    // hairline under the cartridge info
    rule_a  <= (vy == Y_RULE) && (vx >= 10'd40) && (vx < 10'd280);
end

// ------------------------------------------------------------ stage B: character + colour
reg [7:0]  ch_b;
reg [23:0] col_b;
reg        inv_b;       // draw on the highlight bar
reg [2:0]  fy_b, fx_b;
reg        act_b, bar_b, pbar_b, pfill_b, rule_b;
reg [319:0] line;
reg [23:0]  lcol;
always @(*) begin
    item_idx = row_a;
    line = {40{8'h00}};
    lcol = C_FG;
    case (slot_a)
    4'd15: line = {"SaveSiphon", {30{8'h00}}};
    4'd1:  line = t_name;
    4'd2:  begin line = t_sub; lcol = C_DIM; end
    4'd3, 4'd4, 4'd5, 4'd6: begin
        case (ui_mode)
        UI_MENU: begin
            line = t_item;
            if (row_a != 2'd1 && row_a != 2'd3 && no_save && row_a != 2'd2) lcol = C_FAINT;
        end
        UI_BUSY: if (slot_a == 4'd4) line = (status == 5'd0 || status == 5'd21) ? t_head : t_head;
                 else if (slot_a == 4'd6 && status == 5'd7) begin line = t_file; lcol = C_DIM; end
        UI_RESULT: begin
            if (slot_a == 4'd3) begin
                line = (status == 5'd8) ? t_done : t_head;
                lcol = (status == 5'd8) ? C_OK : st_bad ? C_BAD : C_FG;
            end else if (slot_a == 4'd4) begin line = t_det1; lcol = C_DIM; end
            else if (slot_a == 4'd5) begin line = t_det2; lcol = C_DIM; end
            else if (slot_a == 4'd6 && (status == 5'd9 || status == 5'd12)) begin line = t_err; lcol = C_DIM; end
            else if (slot_a == 4'd6 && status == 5'd8) begin line = t_file; lcol = C_DIM; end
        end
        UI_CONFIRM: begin
            if (slot_a == 4'd3) line = t_head;
            else if (slot_a == 4'd4) begin line = t_det1; lcol = C_DIM; end
            else if (slot_a == 4'd5) begin line = t_det2; lcol = C_DIM; end
        end
        default: ;
        endcase
    end
    4'd7: if (ui_mode == UI_MENU) begin
              line = {{6{8'h00}}, "Save", {30{8'h00}}} | t_savev;
              lcol = C_DIM;
          end
    4'd8: if (ui_mode == UI_MENU) begin
              line = (is_gb ? {{6{8'h00}}, "Mapper", {28{8'h00}}} | t_mapv : {{6{8'h00}}, "ROM", {31{8'h00}}} | t_romv);
              lcol = C_DIM;
          end
    4'd9: begin
        lcol = C_DIM;
        case (ui_mode)
        UI_MENU:    line = {{9{8'h00}}, {8'h06, " Choose     ", 8'h01, " Select"}, {10{8'h00}}};
        UI_CONFIRM: line = {{9{8'h00}}, {8'h01, " Continue     ", 8'h02, " Back"}, {10{8'h00}}};
        UI_RESULT:  line = fatal ? {{5{8'h00}}, "Restart the core from the menu", {5{8'h00}}} : (cart_kind == 2'd0 || status == 5'd20) ? {{14{8'h00}}, {8'h01, " Try again"}, {15{8'h00}}} : {{13{8'h00}}, {8'h01, " Back to menu"}, {13{8'h00}}};
        default:    line = (status >= 5'd5 && status != 5'd21) ? {{6{8'h00}}, "Do not remove the cartridge", {7{8'h00}}} : {40{8'h00}};
        endcase
    end
    default: ;
    endcase
end

// the info rows are two columns: label left in grey, value right in white
wire [5:0] info_split = 6'd20;

always @(posedge clk) begin
    ch_b    <= (col_a < 6'd40) ? line[8*(39-col_a) +: 8] : 8'h00;
    col_b   <= ((slot_a == 4'd7 || slot_a == 4'd8) && col_a >= info_split) ? C_FG : lcol;
    inv_b   <= bar_a;
    fy_b    <= fy_a;
    fx_b    <= fx_a;
    act_b   <= act_a;
    bar_b   <= bar_a;
    pbar_b  <= pbar_a;
    pfill_b <= pfill_a;
    rule_b  <= rule_a;
end

// ------------------------------------------------------------ stage C: font row
reg [7:0]  glyph_c;
reg [23:0] col_c;
reg [2:0]  fx_c;
reg        act_c, bar_c, pbar_c, pfill_c, rule_c;
always @(posedge clk) begin
    glyph_c <= font[{ch_b[6:0], fy_b}];
    col_c   <= col_b;
    fx_c    <= fx_b;
    act_c   <= act_b;
    bar_c   <= bar_b;
    pbar_c  <= pbar_b;
    pfill_c <= pfill_b;
    rule_c  <= rule_b;
end

// ------------------------------------------------------------ stage D: pixel
reg [3:0] de_d, hs_d, vs_d;
wire      ink = glyph_c[3'd7 - fx_c];
always @(posedge clk) begin
    if (!act_c)        rgb <= 24'h000000;
    else if (pbar_c)   rgb <= pfill_c ? C_FG : C_FAINT;
    else if (bar_c)    rgb <= ink ? C_BG : C_BAR;
    else if (rule_c)   rgb <= C_FAINT;
    else               rgb <= ink ? col_c : C_BG;

    de_d <= {de_d[2:0], active};
    hs_d <= {hs_d[2:0], (x == 10'd3)};
    vs_d <= {vs_d[2:0], (x == 10'd0 && y == 10'd0)};
    de   <= de_d[2];
    hs   <= hs_d[2];
    vs   <= vs_d[2];
end

endmodule

`default_nettype wire
